-- históricas complexas, PP passivo em política pública,
-- tarefas TOEFL integradas de nível alto
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'past-perfect';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo past-perfect não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 71: PP em análise crítica de políticas públicas
  (cid,71,227,'gap_fill','_____ program _____ (not/deliver) _____ promised outcomes because _____ assumptions on which it _____ (base/passive) _____ (prove) empirically unfounded — _____ very assumptions that _____ (challenge/passive) by _____ independent reviewers before _____ program _____ (launch/passive).','The / had not delivered / the / had been based / had proved / the / had been challenged / independent / the / was launched',NULL,'PP chain: assumptions had been based, proved unfounded, had been challenged — all before launch.','hard'),
  (cid,71,228,'gap_fill','What _____ analysts _____ (characterize) as _____ policy failure _____ (more accurately/be) _____ implementation failure: _____ original design _____ (sound/prove), but _____ capacity to _____ (execute) it _____ (not/build/passive) alongside it.','had characterized / a / was more accurately / an / the / had proved sound / the / execute / had not been built',NULL,'PP "had characterized/proved/not been built" for distinguishing design vs implementation failure.','hard'),
  (cid,71,229,'gap_fill','By _____ time _____ evaluation _____ (commission/passive), _____ damage _____ (already/done/passive), and _____ window for _____ meaningful _____ course correction _____ (close).','the / the / was commissioned / the / had already been done / the / the / had closed',NULL,'PP passive "had been done/closed" = damage and window both prior to evaluation commission.','hard'),
  (cid,71,230,'multiple_choice','Which sentence MOST effectively uses past perfect to analyze a policy failure?','The intervention failed because the institutional capacity needed to implement it had never been developed, despite repeated recommendations to do so.','["The intervention failed because institutional capacity was never developed.","The intervention failed because the institutional capacity needed to implement it had never been developed, despite repeated recommendations to do so.","The intervention had failed because institutional capacity has never been developed.","The intervention was failing because institutional capacity had not yet developed."]','PP "had never been developed" = persistent prior absence; "despite repeated recommendations" reinforces the prior neglect.','medium'),
  (cid,71,231,'gap_fill','_____ reform _____ (design/passive) without _____ adequate _____ (consider) of _____ political economy of _____ implementation — _____ oversight that _____ (prove) fatal, as _____ actors who _____ (most/stand) to _____ (lose) from _____ change _____ (mobilize) to _____ (block) it.','The / had been designed / adequate / consideration / the / an / proved / the / had most stood / lose / the / mobilized / block',NULL,'PP "had been designed/stood" = design failure and who had stood to lose.','hard'),
  (cid,71,232,'gap_fill','_____ (have) _____ evidence _____ (present) to _____ decision-makers in _____ more accessible form, _____ different _____ choices _____ (might/make/passive) — but _____ communication failures that _____ (allow) _____ gap to _____ (develop) between _____ research and _____ policy _____ (not/address/passive) systematically.','Had / the / been presented / to / a / different / choices might have been made / the / had allowed / a / develop / the / had not been addressed',NULL,'Inverted PP conditional: "Had the evidence been presented" + PP "had allowed/not been addressed."','hard'),
  (cid,71,233,'gap_fill','It _____ (become) clear in _____ retrospect that _____ warnings _____ (issue/passive) had _____ (not/hear/passive) — not because they _____ (not/reach) _____ right _____ people but because _____ institutional culture _____ (develop) that _____ (treat) _____ inconvenient information as _____ threat.','became / retrospect / the / that had been issued / had not been heard / had not reached / the / right / an / had developed / treated / inconvenient / a',NULL,'PP "had been issued/heard/reached/developed/treated" in institutional failure analysis.','hard'),

  -- BLOCK 72: PP em sínteses históricas complexas
  (cid,72,234,'gap_fill','_____ revolution _____ (not/inevit/passive) — _____ trajectory that _____ (lead) to it _____ (shape/passive) by _____ contingent _____ decisions and _____ structural conditions that _____ (develop) over _____ preceding century, but _____ (be) different _____ choices _____ (make/passive) at _____ critical _____ junctures, _____ outcome _____ (might/differ).','The / was not inevitable / the / had led / had been shaped / contingent / structural / had developed / the / had different / choices / been made / critical / junctures / the / might have differed',NULL,'PP "had led/been shaped/developed" in historical contingency analysis.','hard'),
  (cid,72,235,'gap_fill','_____ transformation _____ (more gradual/prove) than _____ contemporary accounts _____ (suggest) — _____ elements that _____ (later/recognize/passive) as _____ decisive shift _____ (already/emerge) well before _____ events that _____ (conventionally/mark) _____ change.','The / proved more gradual / the / had suggested / the / were later recognized / a / had already emerged / the / conventionally mark / the',NULL,'PP "had suggested/been recognized/emerged" in historiographical revision.','hard'),
  (cid,72,236,'gap_fill','By _____ end of _____ century, _____ institutions that _____ (once/seem) permanent _____ (transform/passive) beyond _____ recognition, and _____ social arrangements that _____ (govern) _____ daily _____ life for _____ generations _____ (swept away/passive).','the / the / the / had once seemed / had been transformed / all / the / had governed / daily / life / generations / had been swept away',NULL,'PP "had once seemed/been transformed/governed/been swept away" for century-scale historical synthesis.','hard'),
  (cid,72,237,'multiple_choice','Which sentence MOST effectively uses past perfect in historical analysis?','The economic collapse that triggered the political crisis had been building for years in the structural vulnerabilities that previous governments had chosen to ignore.','["The economic collapse that triggered the political crisis built for years in structural vulnerabilities.","The economic collapse that triggered the political crisis had been building for years in the structural vulnerabilities that previous governments had chosen to ignore.","The economic collapse had triggered the political crisis after it built for years.","The economic collapse had been building for years, and previous governments chose to ignore it."]','PP continuous "had been building" + PP "had chosen" = both prior to the collapse event; strongest temporal logic.','medium'),
  (cid,72,238,'gap_fill','What _____ historians _____ (subsequently/identify) as _____ turning point _____ (not/recognize/passive) as such at _____ time — _____ actors _____ (operate) within _____ frameworks of _____ understanding that _____ (not/prepare) them to _____ (perceive) _____ significance of _____ events _____ (unfold) around them.','historians / had subsequently identified / a / had not been recognized / the / the / had operated / the / had not prepared / perceive / the / unfolding',NULL,'PP "had identified/not been recognized/operated/not prepared" in historiographical analysis.','hard'),
  (cid,72,239,'gap_fill','_____ narrative that _____ (dominate) _____ field for _____ generation _____ (undermine/passive) by _____ archival evidence that _____ (surface) in _____ 1990s, _____ (reveal) that _____ key assumptions on which it _____ (rest/passive) _____ (base/passive) on _____ misreading of _____ sources.','The / had dominated / the / a / had been undermined / the / surfaced / the / revealing / the / had rested / had been based / a / the',NULL,'PP "had dominated/been undermined/rested/been based" in scholarly revisionism narrative.','hard'),
  (cid,72,240,'gap_fill','_____ settlement that _____ (reach/passive) at _____ end of _____ conflict _____ (plant) _____ seeds of _____ next one, embedding _____ grievances that _____ (fester) for _____ decades until they _____ (find) _____ expression in _____ renewed _____ violence.','The / had been reached / the / the / had planted / the / the / had festered / the / found / their / renewed',NULL,'PP "had been reached/planted/festered" in historical causation chain.','hard'),

  -- BLOCK 73: PP passivo em textos formais de política
  (cid,73,241,'gap_fill','_____ provisions of _____ agreement _____ (negotiate/passive) over _____ period of _____ three years and _____ (subject/passive) to _____ extensive _____ legal review before _____ final text _____ (submit/passive) for _____ ratification.','The / the / had been negotiated / a / the / had been subjected / extensive / the / was submitted / ratification',NULL,'PP passive "had been negotiated/subjected" before submission for ratification.','medium'),
  (cid,73,242,'gap_fill','_____ methodology _____ (develop/passive) over _____ preceding decade through _____ series of _____ pilot studies and _____ (validate/passive) in _____ multiple national _____ contexts before _____ (deploy/passive) at _____ scale in _____ current program.','The / had been developed / the / a / pilot / had been validated / multiple / before / being deployed / the / the',NULL,'PP passive chain: developed, validated — both before large-scale deployment.','medium'),
  (cid,73,243,'gap_fill','By _____ time _____ legislation _____ (enact/passive), _____ most _____ contentious provisions _____ (already/water down/passive) through _____ process of _____ political negotiation that _____ (strip) them of _____ much of _____ transformative _____ potential they _____ (originally/intend/passive).','the / the / was enacted / the / had already been watered down / a / political / had stripped / them / much / their / that / had originally been intended',NULL,'PP passive "had been watered down/stripped/intended" in legislative dilution analysis.','hard'),
  (cid,73,244,'gap_fill','_____ evidence _____ (assess/passive) by _____ panel of _____ independent _____ experts who _____ (select/passive) for their _____ expertise in _____ relevant fields and who _____ (screen/passive) for _____ potential _____ conflicts of interest before _____ (invite/passive) to _____ (participate).','The / had been assessed / a / the / independent / had been selected / their / the / had been screened / potential / before / being invited / participate',NULL,'PP passive "had been assessed/selected/screened/invited" for expert panel process.','hard'),
  (cid,73,245,'gap_fill','_____ program _____ (base/passive) on _____ model that _____ (pilot/passive) successfully in _____ neighboring country, but _____ adaptations _____ (make/passive) for _____ local context _____ (prove) _____ insufficient to _____ (address) _____ differences that _____ (ultimately/undermine) _____ transfer.','The / had been based / a / had been piloted / the / the / that had been made / the / proved / insufficient / address / the / ultimately undermined / the',NULL,'PP passive "had been based/piloted/made" in policy transfer analysis.','hard'),
  (cid,73,246,'gap_fill','It _____ (subsequently/emerge) that _____ consultation process that _____ (present/passive) as _____ inclusive _____ (in fact/conduct/passive) in _____ way that _____ (systematically/exclude) _____ voices most _____ directly _____ (affect/passive) by _____ decision.','subsequently emerged / the / had been presented / inclusive / had in fact been conducted / a / had systematically excluded / the / those / most / affected / the',NULL,'PP passive chain exposing gap between presented and actual consultation conduct.','hard'),
  (cid,73,247,'gap_fill','By _____ close of _____ review period, _____ committee _____ (receive) _____ submissions, _____ (conduct) _____ public hearings, and _____ (commission) _____ independent _____ technical analyses — _____ (constitute/passive) _____ most _____ comprehensive _____ evidence _____ (base) in _____ history of _____ inquiry.','the / the / the / had received / the / had conducted / the / had commissioned / the / constituting / the / most / comprehensive / evidence / base / the / the',NULL,'PP "had received/conducted/commissioned" = prior activities constituting comprehensive evidence base.','hard'),

  -- BLOCK 74: TOEFL Reading — PP em textos complexos
  (cid,74,248,'multiple_choice','[TOEFL Reading] "By the time the scientific consensus had shifted, the policy window for effective action had already closed." What does this sentence communicate?','The consensus shift came too late — the opportunity for action was already gone before the consensus changed.','["The consensus shifted before the policy window opened","The consensus shift came too late — the opportunity for action was already gone before the consensus changed.","The policy window closed at the same time as the consensus shifted","The consensus shift caused the policy window to close"]','PP "had shifted/had closed" — both in PP, but "already" signals window closed BEFORE consensus; tragic timing.','hard'),
  (cid,74,249,'gap_fill','[TOEFL Reading] "_____ researchers _____ (demonstrate) that _____ intervention _____ (not/produce) _____ outcomes _____ (anticipate) because _____ contextual factors that _____ (shape) its _____ effectiveness _____ (not/adequately/account for/passive)." Best forms?','The / demonstrated / the / had not produced / the / anticipated / the / had shaped / had not been adequately accounted for',NULL,'PP "had not produced/shaped/not been accounted for" = prior failures revealed by research.','hard'),
  (cid,74,250,'gap_fill','[TOEFL Reading] "What _____ planners _____ (originally/envision) as _____ five-year initiative _____ (evolve) into _____ decade-long program as _____ scale of _____ challenge _____ (become) apparent and _____ initial _____ assumptions _____ (revise/passive) in _____ light of _____ early _____ experience." Best forms?','the / had originally envisioned / a / evolved / a / the / the / became / the / initial / assumptions / were revised / the / early',NULL,'PP "had envisioned/revised" for original plan vs evolved reality contrast.','medium'),
  (cid,74,251,'gap_fill','[TOEFL Reading] "_____ discovery _____ (make) by _____ team that _____ (not/aware/passive) of _____ parallel work _____ (conduct/passive) elsewhere — _____ (illustrate) how _____ fragmentation of _____ scientific _____ community _____ (allow) _____ same ground _____ (cover/passive) independently by _____ multiple _____ groups." Best forms?','The / was made / a / had not been aware / the / being conducted / illustrating / the / of / had allowed / the / to be covered / multiple',NULL,'PP "had not been aware/allowed" for scientific community fragmentation illustration.','hard'),

  -- BLOCK 75: TOEFL Speaking — PP em resumos e análises
  (cid,75,252,'production','[TOEFL Speaking — 45s] A reading describes how a technological breakthrough transformed an industry. Use past perfect throughout.','',NULL,'The reading describes how the development of containerization transformed global shipping in ways that had not been anticipated even by the most optimistic proponents of the technology. Before containerization had been adopted, shipping had been a labor-intensive industry in which cargo had been loaded and unloaded piece by piece, a process that had kept ships in port for extended periods and had created significant opportunities for pilferage and damage. The innovators who had developed the standardized container had faced substantial resistance from longshoremen''s unions and port operators who had invested heavily in existing infrastructure. However, once the technology had been demonstrated to reduce costs dramatically, the economic logic had proved irresistible. Within two decades of its introduction, containerization had transformed the geography of global production by making it economically rational to manufacture goods wherever labor costs were lowest and ship them to wherever consumers were located. The reading notes that this transformation had contributed more to the growth of global trade than any trade agreement negotiated during the same period, a fact that had not been fully appreciated by economists who had focused on tariff reductions as the primary driver of trade growth.','hard'),
  (cid,75,253,'production','[TOEFL Speaking — 60s] A professor explains why a social movement succeeded where previous ones had failed. Use past perfect throughout.','',NULL,'The professor argues that the movement succeeded for reasons that distinguished it from the previous movements that had attempted similar goals but had failed to achieve lasting change. She explains that earlier movements had lacked three things that the successful movement had developed. First, earlier movements had relied primarily on moral suasion and had not built the kind of organized political power that could translate public sympathy into legislative outcomes. The successful movement had done both: it had cultivated relationships with political allies and had developed sophisticated voter registration and mobilization operations that gave it genuine political leverage. Second, earlier movements had often been vulnerable to the same internal divisions over strategy and ideology that had limited their effectiveness. The successful movement had managed these tensions more skillfully, having learned from the failures of its predecessors, and had maintained sufficient internal discipline to present a united front even when internal disagreements were significant. Third, earlier movements had operated in political environments where the costs of resistance for political elites had been low; by the time the successful movement emerged, conditions had shifted in ways that had raised these costs, partly because previous movements had contributed to a gradual shift in public opinion that the successful movement had been able to mobilize.','hard'),

  -- BLOCK 76: TOEFL Writing — PP em ensaios analíticos
  (cid,76,254,'production','[TOEFL Writing — 200 words] Write a paragraph analyzing why an institution declined, using past perfect throughout.','',NULL,'The decline of the institution can only be understood in relation to the choices and failures that had accumulated over the preceding two decades and that had hollowed out its capacity and legitimacy before the visible signs of crisis became apparent. The institution had been founded with a clear mandate and had performed that mandate effectively for its first generation of existence, but the conditions that had made it effective had gradually eroded as the political environment changed and as the institution had failed to adapt. Its leadership had consistently prioritized institutional self-preservation over mission effectiveness, had resisted external scrutiny that might have identified the growing gap between performance and mandate, and had allowed a culture of complacency to develop that had made the kind of critical self-assessment required for effective adaptation impossible. Resources that had once been allocated to the core mission had been progressively redirected toward administrative functions that had expanded without generating corresponding improvements in performance. The external oversight mechanisms that had been designed to hold the institution accountable had atrophied as the political will to maintain them had weakened. By the time the scale of the institution''s difficulties had become undeniable, the combination of weakened capacity, damaged credibility, and depleted political support had made recovery extremely difficult to achieve.','hard'),
  (cid,76,255,'production','[TOEFL Writing — 200 words] Write a paragraph on the legacy of colonialism using past perfect throughout.','',NULL,'The economic structures that colonialism had created persisted long after the formal end of colonial rule and had shaped the development trajectories of post-independence states in ways that continued to limit their options decades later. Colonial administrations had oriented economies toward the export of primary commodities and had systematically prevented the development of domestic manufacturing capacity that might have competed with metropolitan industries. The transportation and communication infrastructure that had been built had been designed to facilitate resource extraction rather than to connect domestic markets, leaving newly independent states with infrastructure that had been suited to their role as colonial appendages but had proved poorly adapted to the needs of integrated national economies. Educational systems that had been established had trained populations for subordinate roles in the colonial administration and had provided access to higher education in numbers that had been calculated to prevent the emergence of an educated class that might have challenged colonial authority. The institutions of governance that had been inherited at independence had been designed for administrative control rather than for democratic participation and had been ill-suited to the tasks of nation-building. These legacies had not been immutable — post-independence choices had mattered enormously in determining development outcomes — but they had defined the starting conditions from which post-independence development had proceeded and had constrained the options available.','hard'),

  -- BLOCK 77: TOEFL Writing — PP em sínteses de TOEFL Writing Task 2
  (cid,77,256,'production','[TOEFL Writing — 200 words] Write an analysis paragraph on why international negotiations failed, using past perfect.','',NULL,'The failure of the negotiations can be traced to a set of structural factors that had developed over the years preceding the talks and that had made agreement extremely difficult to achieve regardless of the skill or intentions of the negotiators involved. The parties had entered the talks with positions that had hardened through years of public rhetoric in which leaders had made domestic commitments that constrained their flexibility at the negotiating table. The trust that successful negotiations had historically required had been depleted by a series of episodes in which previous agreements had been unilaterally revised or abandoned, creating a pattern that had made each party reluctant to offer concessions that might not be reciprocated. The technical complexity of the issues had outpaced the institutional capacity that had been developed to analyze and implement agreements, meaning that even where political will had existed, the bureaucratic capability to translate it into implementable commitments had been insufficient. The domestic political conditions that had existed in previous negotiating rounds, and that had made agreement possible then, had since shifted in ways that had reduced the political space for compromise in key countries. The combination of these factors had created what negotiators had recognized as a "valley of failure" — a situation in which each party had preferred the status quo to the compromises required for agreement.','hard'),
  (cid,77,257,'production','[TOEFL Writing — 200 words] Write a paragraph on how prior technological changes had prepared society for a major transition.','',NULL,'The social and economic readiness for the digital revolution had been prepared, in ways that were not fully appreciated at the time, by several decades of incremental changes that had gradually built the infrastructure — technical, institutional, and cognitive — on which the rapid transformation of the 1990s and 2000s would rest. The personal computer revolution that had begun in the 1970s and 1980s had familiarized a generation of workers and consumers with interactive computing and had created a software industry whose capabilities and business models had laid the groundwork for the internet era. The telecommunications deregulation that had occurred in many countries during the 1980s had created conditions in which the investment needed to build internet infrastructure could be mobilized, and the standards-setting processes that had been conducted through international bodies had established the technical protocols on which the global internet had been built. Educational systems had begun to incorporate computing skills into their curricula, and the workforce had developed a baseline digital literacy that had made rapid adoption possible once compelling applications had emerged. The legal and regulatory frameworks that had governed intellectual property, commerce, and privacy had been developed in ways that, while imperfect, had provided sufficient certainty for digital commerce to develop. Each of these developments had been necessary but insufficient on its own; it was their combination that had created the conditions for the transformation that followed.','hard'),

  -- BLOCK 78: TOEFL Writing — PP em paragrafos de contraste e comparação
  (cid,78,258,'production','[TOEFL Writing — 200 words] Compare two countries where one had prepared for a shock and the other had not.','',NULL,'The contrast in outcomes between the two countries following the external shock illustrated with painful clarity the consequences of the different choices that their governments had made during the preceding decade of relative stability. The first country had used the period of favorable conditions to build fiscal buffers, had reformed its financial sector to reduce vulnerabilities, had invested in the human capital and infrastructure that would support resilience, and had developed the social protection systems that could cushion the population against the worst effects of an adverse shock. When the shock arrived, the government had the policy space, the institutional capacity, and the political legitimacy to respond effectively, and the population had the baseline economic security that allowed them to absorb the disruption without the kind of social and political crisis that had accompanied previous episodes of severe economic stress. The second country had instead used the favorable period to expand consumption, had allowed fiscal imbalances to develop, had permitted the financial sector to take on risks that had not been adequately regulated, and had deferred the investments in human capital and infrastructure that would have built long-term resilience. When the same shock struck, the government had neither the fiscal space to respond nor the institutional capacity to implement effective measures, and the population had lacked the buffers that might have prevented the shock from becoming a crisis.','hard'),
  (cid,78,259,'gap_fill','Had _____ decision-makers _____ (heed) _____ warnings that _____ (issue/passive) months before _____ crisis, _____ most _____ severe _____ consequences _____ (might/avoid/passive) — but _____ culture of _____ denial that _____ (develop) within _____ institution _____ (make) it _____ (structurally/difficult) to _____ (acknowledge) _____ information that _____ (contradict) _____ prevailing _____ assumptions.','the / heeded / the / had been issued / the / the / most / severe / consequences / might have been avoided / a / denial / had developed / the / had made / structurally difficult / acknowledge / the / contradicted / the / prevailing',NULL,'Inverted PP conditional "Had decision-makers heeded" + PP "had been issued/developed/made."','hard'),
  (cid,78,260,'gap_fill','_____ comparison _____ (reveal) that _____ countries that _____ (invest) most _____ heavily in _____ public _____ health _____ infrastructure in _____ preceding decade _____ (significantly/outperform) those that _____ (allow) _____ capacity to _____ (atrophy) during _____ period of _____ relative _____ calm.','The / revealed / those / had invested / most / heavily / public / health / the / significantly outperformed / had allowed / their / atrophy / the / relative / calm',NULL,'PP "had invested/allowed/atrophy" in comparative policy outcome analysis.','hard'),
  (cid,78,261,'gap_fill','_____ institutions that _____ (build) _____ strong _____ governance _____ frameworks in _____ years before _____ shock _____ (prove) significantly more _____ resilient than those where _____ such _____ investment _____ (not/make/passive) and where _____ accountability _____ mechanisms _____ (not/function/passive) effectively.','Those / had built / strong / governance / frameworks / the / before / proved / resilient / where / such / had not been made / the / had not been functioning',NULL,'PP "had built/not been made/not been functioning" for comparative institutional resilience.','hard'),

  -- BLOCK 79: Exercícios finais avançados
  (cid,79,262,'gap_fill','_____ evidence _____ (present/passive) systematically _____ (demonstrate) that _____ early _____ interventions that _____ (conduct/passive) with _____ adequate _____ resources and _____ technical _____ support _____ (produce) _____ significantly better _____ outcomes than _____ those _____ (implement/passive) under _____ constraints.','The / presented / demonstrated / the / had been conducted / adequate / technical / had produced / significantly / those / implemented / resource',NULL,'PP "had been conducted/produced" for early intervention effectiveness.','hard'),
  (cid,79,263,'gap_fill','What _____ (seem) at _____ time _____ prudent _____ course of _____ action _____ (prove) in _____ retrospect to _____ (have/been) _____ significant _____ miscalculation — _____ information that _____ (subsequently/surface) _____ (change) _____ assessment _____ fundamentally.','had seemed / the / a / prudent / course / proved / retrospect / to / have been / a / significant / miscalculation / the / subsequently surfaced / changed / the / fundamentally',NULL,'PP "had seemed/have been/surfaced" in retrospective reassessment.','hard'),
  (cid,79,264,'gap_fill','Not until _____ full _____ scope of _____ problem _____ (become) _____ apparent _____ (mobilize/passive) _____ political will _____ (need/passive) to _____ (address) it — by which point _____ options that _____ (previously/available/passive) _____ (longer/no/exist/passive).','the / full / scope / had become / apparent / was mobilized / the / needed / address / the / had previously been available / no longer existed',NULL,'PP "had become/been available" + inversion "not until" for delayed response analysis.','hard'),
  (cid,79,265,'gap_fill','_____ lesson that _____ (draw) from _____ comparative _____ analysis _____ (straightforward) in _____ principle even if _____ (prove) difficult in _____ practice: _____ countries that _____ (invest) early in _____ prevention _____ (consistently/outperform) those that _____ (wait) until _____ crisis _____ (force) _____ action.','The / was drawn / the / comparative / was straightforward / principle / it proved / practice / the / had invested / consistently outperformed / had waited / the / forced / action',NULL,'PP "had invested/waited" in comparative lesson-drawing conclusion.','hard'),
  (cid,79,266,'production','[TOEFL Writing — 200 words] Write a final analytical paragraph on institutional resilience using past perfect throughout.','',NULL,'The institutions that proved most resilient in the face of the crisis were those that had cultivated several characteristics over years of operation that proved valuable precisely when they were most needed. They had developed cultures of honest internal assessment that had allowed problems to be identified and addressed before they became crises. They had built leadership pipelines that had ensured capable individuals were available to navigate difficult circumstances, rather than relying on single individuals whose departure had in other organizations created leadership vacuums at critical moments. They had maintained relationships with external stakeholders — including critics and skeptics — that had provided access to perspectives and information that purely internal processes had systematically missed. They had invested in systems and processes that had reduced dependence on tacit knowledge held by particular individuals and had documented institutional learning in ways that had been accessible to successors. They had also maintained financial buffers and operational flexibility that had created space for adaptation when circumstances had changed in ways that had not been anticipated. In each of these respects, the resilient institutions had made investments during periods of relative stability that had appeared, to those focused on short-term performance metrics, to be inefficient or unnecessary. The crisis had revealed that these investments had been among the most important decisions those institutions had ever made.','hard'),

  -- BLOCK 80: Exercícios gap fill finais com PP passivo
  (cid,80,267,'gap_fill','_____ agreement _____ (reach/passive) after _____ talks that _____ (stretch) over _____ eighteen months, during which _____ positions _____ (test/passive), _____ compromise formulations _____ (explore/passive), and _____ political _____ support _____ (assess/passive) before _____ final _____ text _____ (present/passive) to _____ leaders.','An / was reached / the / had stretched / the / had been tested / the / had been explored / the / had been assessed / the / was presented / the',NULL,'PP passive "had stretched/been tested/explored/assessed" before final text presentation.','hard'),
  (cid,80,268,'gap_fill','_____ vulnerabilities that _____ (expose/passive) by _____ crisis _____ (not/new) — they _____ (identify/passive) in _____ successive _____ reviews and _____ (flag/passive) by _____ analysts, but _____ political will to _____ (address) them _____ (not/materialize/passive) until _____ crisis _____ (make) _____ avoidance _____ (no longer/possible).','The / had been exposed / the / were not new / had been identified / successive / had been flagged / the / address / had not materialized / the / made / avoidance / no longer possible',NULL,'PP passive "had been exposed/identified/flagged/materialized" in crisis retrospective.','hard'),
  (cid,80,269,'gap_fill','By _____ close of _____ negotiation, each _____ party _____ (make) _____ concessions that _____ (initially/describe/passive) as _____ unacceptable, _____ (demonstrate) that _____ positions that _____ (present/passive) as _____ fixed _____ (prove) more _____ flexible when _____ right _____ conditions _____ (create/passive).','the / the / had made / the / had initially been described / demonstrating / the / had been presented / fixed / had proved / the / right / were created',NULL,'PP "had made/been described/been presented/proved/been created" in negotiation flexibility analysis.','hard'),
  (cid,80,270,'gap_fill','What _____ (previously/dismiss) as _____ theoretical _____ possibility _____ (become) _____ urgent _____ policy _____ priority once _____ evidence _____ (accumulate) to _____ point where _____ it _____ (no longer/ignore/passive).','had previously been dismissed / a / theoretical / became / an / urgent / policy / the / had accumulated / a / where / could no longer be ignored',NULL,'PP "had been dismissed/accumulated" + modal "could no longer be ignored" for evidence accumulation.','hard'),

  -- BLOCK 81-83: Exercícios finais de produção e síntese
  (cid,81,271,'production','[TOEFL Writing — 200 words] Write a paragraph on how prior failures had shaped the design of a successful reform.','',NULL,'The reform that ultimately succeeded had been designed with explicit attention to the reasons why previous attempts had failed, and understanding the relationship between prior failure and eventual success reveals important lessons about the conditions under which institutional change becomes possible. The architects of the successful reform had studied the failures of their predecessors carefully and had identified three recurring patterns that had undermined previous efforts. First, previous reformers had underestimated the organizational capacity required for implementation and had designed reforms whose complexity had exceeded the administrative capacity available to execute them. The successful reform had been deliberately simpler, sacrificing theoretical elegance for operational feasibility. Second, previous reforms had failed to build the broad political coalitions needed to sustain change through implementation, relying instead on executive action that had been vulnerable to reversal when the political wind changed. The successful reform had invested heavily in stakeholder engagement before the reform was launched, creating constituencies that had a stake in its success. Third, previous reforms had not built in adequate monitoring and feedback mechanisms that would have allowed course corrections during implementation. The successful reform had established clear metrics, independent monitoring, and formal review processes that had enabled adjustments before small problems had become large ones. In each case, learning from what had previously failed had directly shaped the design choices that had made eventual success possible.','hard'),
  (cid,81,272,'production','[TOEFL Speaking — 60s] Discuss how prior decisions had created path dependencies that constrained later choices. Use past perfect throughout.','',NULL,'The concept of path dependency describes a phenomenon that the reading illustrates well: the decisions that had been made early in a process had constrained the choices available at later stages in ways that often had not been anticipated by those who had made the initial decisions. In the case discussed in the reading, the infrastructure investments that had been made in the first decades of the program had created physical and institutional facts that had subsequently proved extremely difficult to reverse. Organizations had been built around the existing infrastructure, workforces had been trained in skills suited to the existing systems, and political constituencies had developed that had a strong interest in protecting the investments that had been made. By the time the limitations of the original design had become apparent, the costs of switching to a fundamentally different approach had grown so large — because so much had already been invested in the existing path — that even those who had recognized its limitations had concluded that incremental adaptation was more feasible than the radical redesign that the situation had arguably required. The professor extends this analysis to argue that path dependency helps explain why institutions that had once been appropriate continue to persist even after the conditions that had justified their creation have changed, because the costs of switching paths are borne by those who must change while the benefits accrue to future generations who have no voice in the decision.','hard'),
  (cid,81,273,'gap_fill','Had _____ international community _____ (act) on _____ early _____ warnings that _____ (transmit/passive) through _____ multiple _____ channels, _____ scale of _____ subsequent _____ catastrophe _____ (might/significantly/reduce/passive) — but _____ political _____ will that _____ (require/passive) _____ (not/mobilize/passive) until _____ events _____ (already/unfold) beyond _____ capacity to _____ (reverse).','the / acted / the / early / had been transmitted / multiple / the / the / subsequent / might have been significantly reduced / the / political / will / was required / had not been mobilized / the / had already unfolded / the / reverse',NULL,'Inverted PP conditional + PP "had been transmitted/mobilized/unfolded" in humanitarian failure.','hard'),
  (cid,82,274,'gap_fill','_____ analysis _____ (proceed) from _____ assumption that _____ actors _____ (behave) _____ rationally, but _____ evidence _____ (accumulate/passive) over _____ preceding decade _____ (challenge) this _____ foundational _____ premise in ways that _____ (require) _____ revision of _____ theoretical _____ framework.','The / proceeded / the / had behaved / rationally / the / that had accumulated / the / had challenged / this / foundational / had required / a / the / theoretical',NULL,'PP "had accumulated/challenged/required" for theoretical framework revision analysis.','hard'),
  (cid,82,275,'gap_fill','What _____ appeared _____ (be) _____ strong _____ institutional _____ performance _____ (mask/passive) _____ vulnerabilities that _____ (build/passive) beneath _____ surface — _____ vulnerabilities that _____ (expose/passive) only when _____ external _____ shock _____ (remove) _____ favorable _____ conditions that _____ (sustain) _____ appearance of _____ health.','had appeared / to be / strong / institutional / had been masking / that had been building / the / the / were exposed / the / external / removed / the / that had sustained / the / health',NULL,'PP "had appeared/been masking/building/sustained" in institutional vulnerability analysis.','hard'),
  (cid,82,276,'gap_fill','_____ (succeed), _____ initiative _____ (need) to _____ (address) not only _____ surface _____ manifestations of _____ problem but _____ structural _____ conditions that _____ (give) rise to it — conditions that _____ (deep/root/passive) in _____ institutional _____ arrangements that _____ (evolve) over _____ decades and that _____ (not/easily/change/passive).','To succeed / the / needed / address / the / surface / the / the / structural / had given / had been deeply rooted / institutional / had evolved / were not easily changed',NULL,'PP "had given/been rooted/evolved/not easily changed" for structural problem analysis.','hard'),
  (cid,82,277,'gap_fill','_____ (ironically), _____ very _____ success of _____ first phase _____ (contribute) to _____ failure of _____ second: _____ resources that _____ (mobilize/passive) for _____ initial _____ effort _____ (demobilize/passive) on _____ assumption that _____ problem _____ (solve/passive), when in fact _____ (merely/address/passive) _____ most _____ visible _____ symptoms.','Ironically / the / success / the / contributed / the / the / had been mobilized / the / initial / had been demobilized / the / the / had been solved / the / most / visible / symptoms / had merely been addressed',NULL,'PP "had been mobilized/demobilized/solved/addressed" in premature success paradox.','hard'),
  (cid,82,278,'gap_fill','_____ evidence _____ (present) by _____ prosecution _____ (demonstrate) that _____ defendant _____ (aware/be/passive) of _____ risks at _____ time _____ (make) _____ decisions — a finding that _____ (contest/passive) vigorously but that _____ (ultimately/sustain/passive) on _____ basis of _____ contemporaneous _____ documentation that _____ (retrieve/passive) during _____ discovery.','The / presented / the / demonstrated / the / had been aware / the / decisions / were made / had been contested / had ultimately been sustained / the / contemporaneous / had been retrieved / discovery',NULL,'PP "had been aware/contested/sustained/retrieved" in legal evidence chain analysis.','hard'),
  (cid,83,279,'production','[TOEFL Writing — 200 words] Write a final synthesis on what had made a particular era of international cooperation possible.','',NULL,'The unusual degree of international cooperation that characterized the immediate postwar decades can only be understood in relation to the conditions that the Second World War and its aftermath had created — conditions that had fundamentally altered the calculations of the major powers in ways that had made cooperation more attractive than the competitive nationalism that had produced two catastrophic conflicts in a single generation. The war had demonstrated with devastating clarity what the failure of international cooperation could produce, and the elites who had assumed positions of leadership in its aftermath had drawn lessons that had shaped their approach to institution-building. The United States had emerged from the conflict with an unprecedented combination of economic and military preponderance and had concluded that its interests were best served by a stable, rules-based international order rather than by the kind of unilateral dominance that had proved unsustainable for previous hegemons. The Soviet threat had provided a powerful incentive for Western powers to maintain the cohesion that had proved so difficult to sustain in the interwar period, creating a security rationale for the economic cooperation that the architects of the postwar order had sought to institutionalize. The memory of the Great Depression had made elites across the political spectrum receptive to the kind of managed capitalism that the Bretton Woods system had embodied. These conditions had created a window for institution-building that the postwar generation had used to construct the architecture whose legacy, however frayed, continues to shape international relations.','hard'},
  (cid,83,280,'production','[TOEFL Writing — 200 words] Write a concluding paragraph on path dependency and institutional reform using past perfect.','',NULL,'The analysis of path dependency and institutional reform developed in this essay reveals a fundamental tension that lies at the heart of all efforts to change deeply established systems: the very features that make institutions effective — their stability, their embeddedness in social and economic networks, the expectations they have generated — are precisely the features that make them difficult to change, even when the conditions that originally justified their design have shifted. The institutions we have inherited had been built by actors who had faced problems and constraints very different from our own, and who had made choices that had seemed rational given the information and options available to them. Those choices had created path dependencies that have constrained our own choices in ways that we often do not fully appreciate, because we have grown so accustomed to the institutional landscape we have inherited that we have difficulty imagining the alternatives that had once been available. Reform is possible — the historical record had demonstrated this repeatedly — but it typically occurs through the combination of a crisis that had weakened the political position of those who had benefited most from existing arrangements and the availability of actors who had developed alternative institutional designs and had built the coalitions needed to implement them. Understanding these dynamics does not guarantee successful reform, but it identifies more clearly what successful reform has historically required and what had made previous efforts fail.','hard'),
  (cid,83,281,'gap_fill','_____ (reflect) on _____ experience of _____ past _____ generation, it _____ (be) clear that _____ progress _____ (make/passive) _____ (considerable) and that _____ challenges that _____ (once/seem) _____ insurmountable _____ (address/passive) — but it _____ (equally/be) clear that _____ much _____ (remain/passive) to _____ (do) and that _____ (gains/secure/passive) _____ (not/guarantee/passive) to _____ (endure).','Reflecting / the / the / past / is / that / progress / had been made / considerable / the / had once seemed / insurmountable / had been addressed / is equally / that / remains / be done / the / gains / secured / are not guaranteed / endure',NULL,'PP "had been made/seemed/been addressed/secured" in retrospective assessment with forward caution.','hard'),
  (cid,83,282,'gap_fill','In _____ end, what _____ (matter) most _____ (not/be) _____ elegance of _____ design but _____ quality of _____ implementation — _____ lesson that _____ (learn/passive) _____ (repeatedly) throughout _____ history of _____ reform but that _____ (seemingly/need) _____ (learn) _____ (anew) by _____ each _____ generation of _____ reformers.','the / mattered / was not / the / the / the / a / had been learned / repeatedly / the / had seemingly / needed / to be learned / anew / each / generation',NULL,'PP "had been learned/needed" in meta-lesson about recurring reform failure.','hard'),
  (cid,83,283,'production','[TOEFL Speaking — 60s] What had the research revealed about the long-term consequences of an early intervention? Use past perfect throughout.','',NULL,'The longitudinal research discussed in the reading had revealed consequences of the early childhood intervention that had not been fully anticipated when the program had been designed, and that had proved far more significant than the short-term cognitive gains that had originally been the primary focus of evaluation. The children who had participated in the program had demonstrated outcomes across multiple domains that had diverged substantially from those of the control group by the time they had reached adulthood. Their educational attainment had exceeded that of the control group by margins that had grown, rather than shrunk, over time — a finding that had contradicted the "fadeout" hypothesis that had dominated early childhood policy discussions and that had suggested that early gains would be temporary. The economic outcomes that had been tracked in adulthood had shown that participants had achieved significantly higher earnings, had been less likely to have become dependent on public assistance, and had had substantially lower involvement in the criminal justice system. The researchers had calculated that the social return on the investment in the program had far exceeded its cost, largely because of consequences that had extended well beyond the educational domain that had originally motivated the intervention. The reading notes that these findings had arrived too late to influence the policy decisions that had determined the program''s fate, as it had been discontinued before the longitudinal data had accumulated — a sobering illustration of the mismatch between the timescales of policy decisions and the timescales over which the consequences of those decisions had played out.','hard'),
  (cid,83,284,'gap_fill','What _____ (begin) as _____ modest _____ empirical inquiry _____ (evolve) into _____ _____ decades-long _____ research _____ program that _____ (transform) _____ understanding of _____ phenomenon — an evolution that _____ (possible/make/passive) only because _____ original _____ researchers _____ (commit) to _____ (follow) _____ subjects _____ (sufficient/long) to _____ (capture) _____ full _____ arc of _____ consequences.','had begun / a / modest / had evolved / a / decades-long / research / transformed / the / an / had been made possible / the / original / had committed / following / the / sufficiently long / capture / the / full / arc / the',NULL,'PP "had begun/evolved/been made possible/committed" for longitudinal research design.','hard'),
  (cid,83,285,'gap_fill','None of _____ outcomes _____ (foresee/passive) when _____ initial _____ decisions _____ (make/passive), and _____ actors who _____ (make) them _____ (cannot/know) that their _____ choices _____ (set) in _____ motion _____ processes whose _____ full _____ implications _____ (not/reveal/passive) for _____ decades.','the / had been foreseen / the / were made / the / had made / could not have known / choices / had set / in / motion / whose / full / had not been revealed / decades',NULL,'PP "had been foreseen/made/set/not been revealed" for unintended long-term consequence analysis.','hard'),
  (cid,83,286,'gap_fill','By _____ time _____ full _____ implications _____ (become) _____ apparent, _____ choices that _____ (determine) _____ trajectory _____ (already/lock/passive) in — not through _____ any _____ deliberate _____ decision but through _____ accumulated _____ weight of _____ commitments that _____ (make/passive) _____ incrementally and that _____ (seemed) _____ individually _____ reversible but _____ (prove) _____ collectively _____ binding.','the / the / full / implications / became / apparent / the / had determined / the / had already been locked / not / any / deliberate / the / accumulated / the / had been made / incrementally / had seemed / individually / reversible / had proved / collectively / binding',NULL,'PP "had determined/been locked/been made/seemed/proved" in path lock-in analysis.','hard'),
  (cid,83,287,'production','[TOEFL Writing — 200 words] Final essay conclusion: the lessons that historical analysis had taught about institutional change.','',NULL,'The lessons that historical analysis had taught about institutional change are simultaneously encouraging and sobering. The encouraging lesson is that profound change is possible: institutions that had seemed permanent had been transformed, arrangements that had appeared immutable had been reformed, and problems that had resisted solution for generations had been addressed when the political and social conditions had aligned in ways that made change achievable. The history of successful institutional reform had demonstrated that the obstacles that appear insuperable at any given moment are not permanent features of the landscape but products of specific configurations of interests, ideas, and institutions that can shift. The sobering lesson is that change is not inevitable, not always for the better, and not always lasting. Reforms that had seemed transformative had been reversed when the coalitions that had sustained them had fragmented. Improvements that had been achieved had been undermined by changes in other parts of the system that had not been anticipated. The gains that had been made had rarely been consolidated without sustained effort to defend and build upon them. What the historical record had most consistently demonstrated was that successful institutional change required not only the creativity to envision better arrangements but the political intelligence to build the coalitions needed to achieve them and the institutional wisdom to design them so that the interests they created would be powerful enough to sustain them over time. This was the lesson that all previous reformers had learned, and that each generation of reformers had needed to learn again.','hard'),
  (cid,83,288,'gap_fill','Had _____ reformers _____ (study) _____ history more _____ carefully, they _____ (might/avoid) _____ mistakes that _____ (prove) _____ costly — but _____ hubris that _____ (accompany) _____ moments of _____ apparent _____ opportunity _____ (often/make) it _____ (difficult) to _____ (learn) from _____ those who _____ (try) before and _____ (fall short).','the / studied / the / more / might have avoided / the / proved / costly / the / that had accompanied / the / apparent / opportunity / had often made / difficult / learn / those / had tried / had fallen short',NULL,'Inverted PP conditional + PP "had accompanied/made/tried/fallen short" for reform hubris analysis.','hard'),
  (cid,83,289,'gap_fill','_____ generation of _____ reformers that _____ (come) before _____ (leave) _____ an _____ imperfect but _____ (nonetheless/valuable) legacy: _____ institutions _____ (build) imperfectly but _____ (build) nonetheless, _____ norms _____ (establish/passive) that _____ (constrain) if not _____ eliminate _____ worst _____ behaviors, _____ precedents _____ (set/passive) that _____ (make) _____ subsequent _____ progress _____ (easier) than it _____ (otherwise/been).','The / had come / before / had left / an / imperfect / nonetheless valuable / the / institutions / had built / were built / the / had been established / constrained / eliminate / the / the / precedents / had been set / had made / subsequent / easier / would otherwise have been',NULL,'PP "had come/built/been established/been set/made/been" for generational reform legacy.','hard'),
  (cid,83,290,'production','[TOEFL Writing — 200 words] Write a final capstone paragraph using past perfect to synthesize historical lessons about international cooperation.','',NULL,'The history of international cooperation that this analysis had examined reveals a pattern that is at once hopeful and humbling: cooperation of a depth and durability that had once seemed impossible had been achieved when the conditions were right, but those conditions had proved fragile and the achievements had required sustained effort to maintain. The institutions that had been built in the aftermath of historical crises had reflected the lessons that their architects had drawn from the failures that had preceded them, and had embodied an ambition to do better that had generated genuine, if imperfect, progress. The norms that had been established had constrained behavior in ways that had contributed to a less violent and more prosperous world than the one in which the previous generation had grown up. At the same time, the limits of what had been achieved had been real: the distribution of the gains from cooperation had remained unequal, the institutions that had been built had proved better at serving the interests of the powerful than at protecting the interests of the vulnerable, and the progress that had been made had been reversed in several domains when the political will to sustain it had weakened. The task for the present generation is not to replicate what previous generations had built, but to build upon what they had achieved while correcting what they had failed to get right — and to do so with a clarity about the difficulty of the task that those who had attempted it before had not always maintained.','hard'),
  (cid,83,291,'gap_fill','_____ (conclude), _____ past _____ (serve) not as _____ blueprint to _____ (reproduce) but as _____ resource to _____ (learn) from — _____ catalog of _____ what _____ (succeed), what _____ (fail), and _____ what _____ conditions _____ (make) _____ difference between _____ two.','To conclude / the / serves / a / reproduce / a / learn / a / what / had succeeded / what / had failed / the / what / had made / the / the / two',NULL,'PP "had succeeded/failed/made" in meta-historical concluding formulation.','medium'),
  (cid,83,292,'gap_fill','_____ challenge that _____ (face) _____ present _____ generation _____ (not/be) _____ lack of _____ knowledge about what _____ (need) to _____ (do) — _____ necessary _____ reforms _____ (identify/passive) _____ (repeatedly) by _____ successive _____ analysts — but _____ absence of _____ political _____ will to _____ (do) what _____ already _____ (know/passive) to _____ (be) _____ necessary.','The / facing / the / present / is not / a / knowledge / needs / be done / the / necessary / had been identified / repeatedly / successive / the / of / political / will / do / is already / known / to be / necessary',NULL,'PP "had been identified/known" for knowledge-will gap in contemporary reform analysis.','hard'),
  (cid,83,293,'gap_fill','Nothing that _____ (attempt/passive) _____ (be) easy, nothing that _____ (achieve/passive) _____ (certain/be) to _____ (endure), and nothing that _____ (fail) _____ (beyond/be) _____ possibility of _____ (eventual/repair) — _____ (be) _____ realistic _____ assessment with which _____ those who _____ (study) _____ history of _____ reform _____ must _____ (begin).','had been attempted / was / had been achieved / was certain / endure / had failed / was beyond / the / eventual / a / this is / a / realistic / those / have studied / the / must begin',NULL,'PP "had been attempted/achieved/failed" in tripartite realistic assessment conclusion.','hard'),
  (cid,83,294,'production','[TOEFL Writing — 200 words] Final paragraph: what the evidence had demonstrated about the relationship between economic growth and democratic governance.','',NULL,'The relationship between economic development and democratic governance had proved, over decades of research and the accumulation of historical experience, to be more complex and more contingent than either optimistic or pessimistic accounts had suggested. The modernization theory that had dominated mid-twentieth century social science had predicted a relatively straightforward causal relationship: as societies had become wealthier and more educated, they would develop the middle classes and civil society organizations that had been associated with democratic governance in the historical experience of Western Europe and North America. This prediction had been partially confirmed and substantially complicated by the evidence that had accumulated since. The East Asian developmental states had demonstrated that rapid economic development could be achieved under authoritarian governance, complicating the assumption that democracy was a prerequisite for growth. The transitions to democracy that had occurred in the late twentieth century had demonstrated that democratic change was possible at income levels far below those that modernization theory had suggested were necessary. But the democratic backsliding that had occurred in several countries that had achieved significant economic development had revealed that economic growth did not guarantee democratic consolidation and that the relationship between prosperity and democracy was mediated by institutional, cultural, and geopolitical factors that economic models had often treated as secondary. What the evidence had most clearly demonstrated was that neither economic growth nor democratic governance could be assumed to follow automatically from the other, and that both required sustained political effort and institutional investment that had not always been forthcoming.','hard'),
  (cid,83,295,'gap_fill','_____ evidence _____ (examine) in _____ paper _____ (suggest) that _____ relationship _____ (more complex/be) than _____ simple _____ models _____ (capture) and that _____ progress _____ (more fragile/be) than _____ optimistic _____ accounts _____ (acknowledge) — but also that _____ change _____ (more possible/be) than _____ pessimistic _____ accounts _____ (allow).','The / examined / this / suggests / the / had been more complex / the / had captured / the / had been more fragile / the / optimistic / had acknowledged / that / had been more possible / the / pessimistic / had allowed',NULL,'PP "had been/captured/acknowledged/allowed" in balanced evidence conclusion.','hard'),
  (cid,83,296,'gap_fill','What _____ (appear) at _____ outset as _____ intractable _____ problem _____ (prove) amenable to _____ solution once _____ understanding of _____ underlying _____ dynamics _____ (deepen) sufficiently and _____ institutional _____ capacity to _____ (act) on _____ that _____ understanding _____ (develop).','had appeared / the / an / intractable / proved / the / our / the / underlying / had deepened / the / institutional / act / that / had developed',NULL,'PP "had appeared/deepened/developed" in solution emergence analysis.','medium'),
  (cid,83,297,'gap_fill','_____ trajectory of _____ reform _____ (not/linear) — _____ (mark/passive) by _____ setbacks and _____ reversals as well as _____ advances — and _____ (remain) _____ uncertain at _____ points where _____ those _____ (most/invest/passive) in _____ outcome _____ (most/tempted) to _____ (assume) _____ success.','The / had not been linear / it had been marked / setbacks / reversals / advances / had remained / uncertain / the / those / most invested / the / were most tempted / assume / success',NULL,'PP "had not been linear/been marked/remained/invested/been tempted" for non-linear reform trajectory.','hard'),
  (cid,83,298,'gap_fill','_____ (ironically), _____ greatest _____ threats to _____ progress _____ (come) not from _____ explicit _____ opposition but from _____ complacency of _____ those who _____ (achieve) _____ partial _____ success and _____ (mistake) it for _____ completion of _____ task that _____ (barely/begin/passive).','Ironically / the / greatest / the / had come / explicit / the / those / had achieved / partial / had mistaken / the / the / had barely begun',NULL,'PP "had come/achieved/mistaken/begun" for complacency-as-threat analysis.','hard'),
  (cid,83,299,'production','[TOEFL Speaking — 60s] The professor argues that what had seemed like failures had ultimately contributed to later successes. Summarize.','',NULL,'The professor develops a counterintuitive argument that challenges the conventional understanding of the relationship between failure and success in institutional development. She argues that many of the efforts that had appeared to fail at the time had made essential contributions to the successes that eventually followed, through mechanisms that had not been immediately apparent. First, failed efforts had generated knowledge about what had not worked and why, knowledge that had proved invaluable to later reformers who had studied the failures carefully and had designed their approaches to avoid repeating them. Second, failed movements and initiatives had developed the organizational capacity, the leadership skills, and the interpersonal networks that had been available for mobilization when conditions had become more favorable. The civil rights activists who had been involved in earlier efforts that had not produced legislative change had developed the skills and relationships that had made the successful movement possible. Third, failed efforts had shifted the terms of public debate in ways that had made subsequent success more achievable, even when they had not produced immediate policy change. Positions that had seemed radical when earlier advocates had articulated them had gradually moved to the mainstream, in part because those advocates had persistently made the case for them. The professor concludes that understanding failure as a necessary component of the process by which successful change is eventually achieved changes the assessment of what had appeared to be dead ends.','hard'),
  (cid,83,300,'production','[TOEFL Writing — Final capstone 200 words] Write a concluding paragraph synthesizing what past perfect analysis had revealed about the nature of historical causation.','',NULL,'The use of the past perfect throughout this analysis has served not merely as a grammatical requirement but as an analytical tool that has forced attention to a truth about historical causation that more superficial accounts often obscure: that events are not self-caused but are products of prior conditions and decisions that had accumulated over time and that had shaped the range of outcomes that were possible at any given moment. The crises we had examined had not emerged from nowhere but had developed from vulnerabilities that had been building for years or decades before the moment of rupture. The successes we had analyzed had not occurred spontaneously but had rested on foundations that had been constructed through sustained effort, on coalitions that had been built through patient political work, and on ideas that had been developed and refined through extended intellectual labor. The failures we had traced had resulted not from singular errors but from the compounding of choices that had each seemed reasonable at the time but that had in combination created the conditions for collapse. This temporal depth — the insistence on asking not only what happened but what had happened before to make it possible — is what distinguishes genuine historical analysis from narrative description. It is, in the end, what the past perfect is for: to mark the difference between events and the conditions that had made them possible.','hard')

